from typing import Any, TypeGuard


def is_user_rows(rows: list[Any]) -> TypeGuard[list[dict]]:
    return isinstance(rows[0], dict)


def emails(rows: list[Any]) -> list[str]:
    if is_user_rows(rows):
        return [r["email"].lower() for r in rows]
    return []


def primary_email(row: Any) -> str:
    return row.get("email")  # type: ignore
